# 上传文件过滤：扩展名为 .png（不区分大小写）时视为图片。


def is_image(filename):
    return filename.endswith(".PNG")

verification_tests:
from target import is_image


def test_uppercase_extension():
    assert is_image("a.PNG") is True


def test_non_image_extension():
    assert is_image("a.txt") is False


def test_lowercase_extension():
    assert is_image("a.png") is True
